{"path": "stage1.py", "content": """"Stage 1: parse the orders CSV into typed dictionaries."""

import csv


def parse_orders(path):
    """Read a CSV with header ``id,qty,price`` and return a list of dicts.

    Every value is converted to ``int``. Row order is preserved exactly as it
    appears in the file.
    """
    rows = []
    with open(path, newline="") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            rows.append(
                {
                    "id": int(row["id"]),
                    "qty": int(row["qty"]),
                    "price": int(row["price"]),
                }
            )
    return rows
"}

{"path": "stage2.py", "content": """"Stage 2: drop rows that carry no quantity."""


def filter_orders(rows):
    """Return the rows with ``qty > 0``, preserving the original order."""
    return [row for row in rows if row["qty"] > 0]
"}

{"path": "stage3.py", "content": """"Stage 3: aggregate quantities per price."""


def total_by_price(rows):
    """Return ``{price: total_qty}`` summing the quantities of equal prices."""
    totals = {}
    for row in rows:
        totals[row["price"]] = totals.get(row["price"], 0) + row["qty"]
    return totals
"}

{"path": "stage4.py", "content": """"Stage 4: render the totals as a newline-terminated report."""


def report(totals):
    """Render ``"<price>:<qty>"`` per line, prices ascending, trailing newline."""
    lines = [f"{price}:{totals[price]}" for price in sorted(totals)]
    return "".join(line + "\n" for line in lines)
"}
